pub(super) const CONTAINERS: &str = "EXISTS (SELECT 1 FROM capacity_reservation_bootstrap_containers resource WHERE resource.reservation_id={r} AND resource.create_state!='unclaimed' AND resource.container_id IS NULL AND NOT EXISTS (SELECT 1 FROM capacity_reservation_unbound_creation_targets target WHERE target.reservation_id=resource.reservation_id AND target.resource_kind='container' AND target.role=resource.role AND target.docker_name=resource.container_name))";
pub(super) const VOLUMES: &str = "EXISTS (SELECT 1 FROM capacity_reservation_provisioning_objects resource WHERE resource.reservation_id={r} AND resource.create_state!='unclaimed' AND resource.docker_id IS NULL AND NOT EXISTS (SELECT 1 FROM capacity_reservation_unbound_creation_targets target WHERE target.reservation_id=resource.reservation_id AND target.resource_kind='volume' AND target.role=resource.role AND target.docker_name=resource.docker_name AND target.docker_id=resource.docker_name))";
pub(super) const NETWORKS: &str = "EXISTS (SELECT 1 FROM capacity_reservation_networks resource WHERE resource.reservation_id={r} AND resource.network_id IS NULL AND NOT EXISTS (SELECT 1 FROM capacity_reservation_unbound_creation_targets target WHERE target.reservation_id=resource.reservation_id AND target.resource_kind='network' AND target.role='private' AND target.docker_name=resource.network_name))";
pub(super) const RESOURCE_MATCH: &str = "(({t}.resource_kind='container' AND EXISTS (SELECT 1 FROM capacity_reservation_bootstrap_containers resource WHERE resource.reservation_id={t}.reservation_id AND resource.role={t}.role AND resource.container_name={t}.docker_name AND resource.create_state!='unclaimed' AND (resource.container_id IS NULL OR resource.container_id={t}.docker_id))) OR ({t}.resource_kind='volume' AND {t}.docker_id={t}.docker_name AND EXISTS (SELECT 1 FROM capacity_reservation_provisioning_objects resource WHERE resource.reservation_id={t}.reservation_id AND resource.role={t}.role AND resource.docker_name={t}.docker_name AND resource.create_state!='unclaimed' AND (resource.docker_id IS NULL OR resource.docker_id={t}.docker_id))) OR ({t}.resource_kind='network' AND {t}.role='private' AND EXISTS (SELECT 1 FROM capacity_reservation_networks resource WHERE resource.reservation_id={t}.reservation_id AND resource.network_name={t}.docker_name AND resource.connection_id={t}.connection_id AND resource.operation_id={t}.operation_id AND resource.engine_id={t}.engine_id AND resource.docker_root_digest={t}.docker_root_digest AND (resource.network_id IS NULL OR resource.network_id={t}.docker_id))))";
